import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Next's app router ignores directories that start with a dot, so the ARD
  // catalog is generated by a normal route and surfaced at the well-known path.
  async rewrites() {
    return [
      {
        source: "/.well-known/ai-catalog.json",
        destination: "/api/ai-catalog",
      },
    ];
  },
};

export default nextConfig;
